 for(let x=0;x<W;x++){const c=2*x/W-1,dx=camDX+planeX*c,dy=camDY+planeY*c;skyColumns[x]=sky?Math.floor(s4SkyU(Math.atan2(dy,dx))*sky.w):0;skyRayLength[x]=Math.hypot(dx,dy);}
