  if(hgIndoorTree(plant))continue;
  const dx=plant.x-player.x,dy=plant.y-player.y,d=dx*camDX+dy*camDY,cross=dy*camDX-dx*camDY;
  if(d<=.08||Math.abs(cross)>d*W/(2*projection)+plant.w*.6)continue;
