 panel([[-.825,-1.425,.17],[.825,-1.425,.17],[.825,-1.425,.58],[-.825,-1.425,.58]],prefix+'Front');
 panel([[.825,1.425,.17],[-.825,1.425,.17],[-.825,1.425,.59],[.825,1.425,.59]],prefix+'Rear');
